export const title = "How to Fit a Lockable File Cabinet Under a Desk";
export const metaTitle = "How to Fit a Lockable File Cabinet Under a Desk";
export const metaDescription = "Measure the clear bay between the desk supports, the lowest underside obstruction, and the available depth. Add the cabinet's handles, casters, lock.";
export const author = "Jamie Cole, Lead Product Researcher";
export const datePublished = "2026-11-10";
export const readTime = "11 min";
